const items = $input.all();
const content = items[0].json.message.content;

let comparison;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/s);
  comparison = jsonMatch ? JSON.parse(jsonMatch[0]) : { summary: content };
} catch (e) {
  comparison = { summary: content, parseError: true };
}

const textA = $('Webhook').item.json.body.textA || '';
const textB = $('Webhook').item.json.body.textB || '';

// Word-level stats
const wordsA = textA.split(/\s+/).length;
const wordsB = textB.split(/\s+/).length;

return [{
  json: {
    similarity: comparison.similarity || 0,
    textALength: wordsA,
    textBLength: wordsB,
    lengthDiff: wordsB - wordsA,
    differences: comparison.differences || [],
    added: comparison.added || [],
    removed: comparison.removed || [],
    modified: comparison.modified || [],
    toneChanges: comparison.toneChanges || 'None detected',
    summary: comparison.summary || '',
    comparedAt: new Date().toISOString()
  }
}];

parameters.message:
=Text Comparison Report

Similarity: {{ $json.similarity }}%
Text A: {{ $json.textALength }} words | Text B: {{ $json.textBLength }} words

Summary: {{ $json.summary }}

Key Differences:
{{ $json.differences.map((d, i) => `${i+1}. ${d}`).join('\n') }}

Added: {{ $json.added.join('; ') }}
Removed: {{ $json.removed.join('; ') }}
